INSERT INTO iam_role_revisions SELECT r.company_id,r.id,r.published_revision+1,v.permissions_json||'["records.read","records.write"]'::jsonb,CASE WHEN r.id IN ('holding_owner','hr_admin') THEN v.grantable_json||'["records.read","records.write"]'::jsonb ELSE v.grantable_json END,v.scopes_json,'system',0 FROM iam_roles r JOIN iam_role_revisions v ON v.company_id=r.company_id AND v.role_id=r.id AND v.revision=r.published_revision WHERE r.built_in AND r.company_id='*';
