-- Add live record permissions without modifying existing grant validity or history.
CREATE OR REPLACE FUNCTION iam_role_allows(role_key TEXT,company_key TEXT,permission_key TEXT) RETURNS BOOLEAN LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM iam_roles r JOIN iam_role_revisions v ON v.company_id=r.company_id AND v.role_id=r.id AND v.revision=r.published_revision JOIN iam_permissions p ON p.id=permission_key AND p.definition->>'availability'='live' WHERE r.id=role_key AND r.company_id IN ('*',company_key) AND r.status='active' AND v.permissions_json @> jsonb_build_array(permission_key)); $$;
UPDATE iam_roles SET published_revision=published_revision+1 WHERE built_in AND company_id='*';
UPDATE assignments SET version=version+1;
UPDATE active_work_contexts SET assignment_id=NULL,assignment_version=NULL,revision=revision+1;

-- Protect recovery grants reached through parent assignments, including parent revocation.
CREATE OR REPLACE FUNCTION iam_recovery_protect() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE affected BOOLEAN; safe BOOLEAN;
BEGIN
 IF OLD.revoked_at IS NULL AND (NEW.revoked_at IS NOT NULL OR NEW.role!=OLD.role OR NEW.valid_until<OLD.valid_until OR NEW.parent_id IS DISTINCT FROM OLD.parent_id) THEN
 WITH RECURSIVE candidates AS (SELECT a.id FROM assignments a JOIN iam_members m ON m.user_id=a.user_id AND a.company_id=m.company_id WHERE m.company_id=OLD.company_id AND m.login_policy='emergency' AND m.status='active' AND a.role='holding_owner' AND iam_assignment_active(a.id,floor(extract(epoch FROM clock_timestamp())*1000)::bigint)), ancestry(root,id,parent_id,path) AS (SELECT a.id,a.id,a.parent_id,ARRAY[a.id] FROM assignments a JOIN candidates c ON c.id=a.id UNION ALL SELECT r.root,a.id,a.parent_id,r.path||a.id FROM ancestry r JOIN assignments a ON a.id=r.parent_id WHERE NOT a.id=ANY(r.path)) SELECT EXISTS(SELECT 1 FROM ancestry WHERE id=OLD.id),EXISTS(SELECT 1 FROM candidates c WHERE NOT EXISTS(SELECT 1 FROM ancestry r WHERE r.root=c.id AND r.id=OLD.id)) INTO affected,safe;
 IF affected AND NOT safe THEN RAISE EXCEPTION 'The final recovery administrator must remain available' USING ERRCODE='23514'; END IF;
 END IF; RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION assignment_role_scope_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM iam_roles r JOIN iam_role_revisions v ON v.company_id=r.company_id AND v.role_id=r.id AND v.revision=r.published_revision WHERE r.id=NEW.role AND r.company_id IN ('*',NEW.company_id) AND r.status='active' AND v.scopes_json @> jsonb_build_array(NEW.scope_kind)) THEN RAISE EXCEPTION 'Invalid role scope' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION assignment_role_scope_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM iam_roles r JOIN iam_role_revisions v ON v.company_id=r.company_id AND v.role_id=r.id AND v.revision=r.published_revision WHERE r.id=NEW.role AND r.company_id IN ('*',NEW.company_id) AND r.status='active' AND v.scopes_json @> jsonb_build_array(NEW.scope_kind)) THEN RAISE EXCEPTION 'Invalid role scope' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
